export type WorkTrackerMutationState =
  | "queued" | "admitted" | "dispatched" | "reconciling" | "terminal";

export type WorkTrackerMutationOutcome =
  | "applied" | "stale_basis" | "denied_capability" | "unsupported_guarantee"
  | "cancelled" | "timeout" | "ambiguous_external_effect" | "retry_exhausted"
  | "recovery_required" | "external_state_conflict" | "reconsideration_abandoned";

/** Provider-neutral owner-private coordinator record. Provider payloads and tokens stay in adapter evidence. */
export interface WorkTrackerMutationAttemptRecord {
  commandId: string;
  effectId: string;
  rootIntentId: string;
  predecessorCommandId?: string;
  attemptOrdinal: number;
  decision: "original" | "merge" | "rewrite" | "abandon";
  actorSessionId: string;
  actorSessionEpoch: string;
  capabilityAssignmentHash: string;
  projectId: string;
  taskId: string;
  bindingId: string;
  providerId: string;
  adapterVersion: string;
  targetId: string;
  operation: string;
  requiredGuarantee: string;
  availableGuarantee: string;
  basisId: string;
  basisDigest: string;
  payloadDigest: string;
  conflictScope: string;
  queueOrdinal: number;
  state: WorkTrackerMutationState;
  outcome?: WorkTrackerMutationOutcome;
  cancellationRequested: boolean;
  deadlineAt: string;
  providerAttemptCount: number;
  reconciliationAttemptCount: number;
  recoveryState?: string;
  createdAt: string;
  updatedAt: string;
}

export interface ProjectPlanningRecord {
  project: RegisteredProject & {
    activePlanningAuthorityId?: string;
    mergeBarrierState: string;
    mergeBarrierRevision: number;
  };
  /** All task-scoped authority lineages for the project. */
  authorities: PlanningAuthorityRecord[];
  /** Compatibility projection for pre-concurrent-planner callers. */
  authority?: PlanningAuthorityRecord;
  queuedReplans: ReplanRequestRecord[];
