export interface WorkTrackerCoordinatorScope {
  actorSessionId: string;
  actorSessionEpoch: string;
  capabilityAssignmentHash: string;
  projectId: string;
  taskId: string;
  bindingId: string;
  providerId: string;
  adapterVersion: string;
  targetId: string;
  basisId: string;
  basisDigest: string;
  payloadDigest: string;
  rootIntentId: string;
  predecessorCommandId?: string;
  attemptOrdinal: number;
  decision: "original" | "merge" | "rewrite" | "abandon";
}

export interface WorkTrackerFinished<T> {
  value: T;
  outcome: WorkTrackerMutationOutcome;
  recoveryState?: string;
}

export type WorkTrackerPreparation<T> =
  | ({ kind: "terminal" } & WorkTrackerFinished<T>)
  | {
    kind: "dispatch";
    dispatch(signal: AbortSignal): Promise<WorkTrackerFinished<T>>;
    reconcile(reason: "timeout" | "error" | "restart", signal: AbortSignal): Promise<WorkTrackerFinished<T>>;
  };

export interface WorkTrackerMutationSubmission<T> {
  commandId: string;
  scope: WorkTrackerCoordinatorScope;
  capability: WorkTrackerOperationCapability;
  requiredGuarantee: string;
  /** Compatibility recovery hint for a legacy adapter row that predates coordinator admission. */
  recoverAsDispatched?: boolean;
  duplicateValue: T;
  authorize(): void | Promise<void>;
  /** Each phase must honor its signal before new I/O or durable outcome writes. */
  prepare(signal: AbortSignal): Promise<WorkTrackerPreparation<T>>;
  recover(signal: AbortSignal): Promise<WorkTrackerFinished<T>>;
  finishWithoutDispatch(outcome: "denied_capability" | "unsupported_guarantee" | "cancelled" | "timeout"): T | Promise<T>;
  finishRecoveryRequired(recoveryState: string): T | Promise<T>;
}

export interface WorkTrackerMutationStatus {
  commandId: string;
  rootIntentId: string;
  predecessorCommandId?: string;
  attemptOrdinal: number;
  decision: WorkTrackerCoordinatorScope["decision"];
  projectId: string;
  taskId: string;
  providerId: string;
  bindingId: string;
  targetId: string;
  operation: string;
  basisDigest: string;
  conflictScope: string;
  queueOrdinal: number;
  queuePosition: number;
  state: WorkTrackerMutationAttemptRecord["state"];
  outcome?: WorkTrackerMutationOutcome;
  requiredGuarantee: string;
  availableGuarantee: string;
  ageMs: number;
  recoveryState?: string;
}

interface RuntimeEntry<T> {
  attempt: WorkTrackerMutationAttemptRecord;
  submission: WorkTrackerMutationSubmission<T>;
  resolve(value: T): void;
  reject(error: unknown): void;
  timer?: NodeJS.Timeout;
  active: boolean;
}

/**
 * Owner-local, provider-neutral FIFO coordinator. Adapters retain provider
 * requests, credentials, revision tokens, and reconciliation proof.
 */
export class WorkTrackerMutationCoordinator {
  private readonly queues = new Map<string, RuntimeEntry<unknown>[]>();
  private readonly inFlight = new Map<string, Promise<unknown>>();

  constructor(private readonly options: {
    store: TrackedTaskStore;
    maxQueueWaitMs?: number;
    providerDeadlineMs?: number;
    now?: () => Date;
  }) {
    assertPositiveBound(options.maxQueueWaitMs ?? DEFAULT_WORK_TRACKER_MAX_QUEUE_WAIT_MS, "queue wait");
    assertPositiveBound(options.providerDeadlineMs ?? DEFAULT_WORK_TRACKER_PROVIDER_DEADLINE_MS, "provider deadline");
  }

  submit<T>(submission: WorkTrackerMutationSubmission<T>): Promise<T> {
    const existingPromise = this.inFlight.get(submission.commandId);
    if (existingPromise) return existingPromise as Promise<T>;
    const now = this.now();
    const attempt = this.options.store.registerWorkTrackerMutationAttempt({
      commandId: submission.commandId,
      effectId: randomUUID(),
      ...submission.scope,
      operation: submission.capability.operation,
      requiredGuarantee: submission.requiredGuarantee,
      availableGuarantee: submission.capability.guarantee,
      conflictScope: submission.capability.conflictScope,
      deadlineAt: new Date(now.getTime() + this.maxQueueWaitMs).toISOString()
    });
    let scheduledAttempt = attempt;
    if (scheduledAttempt.state === "terminal") return Promise.resolve(submission.duplicateValue);
    if (scheduledAttempt.state === "queued" && submission.recoverAsDispatched) {
      this.options.store.transitionWorkTrackerMutation({ commandId: submission.commandId, state: "admitted" });
      scheduledAttempt = this.options.store.transitionWorkTrackerMutation({ commandId: submission.commandId, state: "dispatched" });
    }

    const promise = new Promise<T>((resolve, reject) => {
      const entry: RuntimeEntry<T> = { attempt: scheduledAttempt, submission, resolve, reject, active: false };
      const key = queueKey(scheduledAttempt);
      const queue = this.queues.get(key) ?? [];
      queue.push(entry as RuntimeEntry<unknown>);
      queue.sort((left, right) => left.attempt.queueOrdinal - right.attempt.queueOrdinal);
      this.queues.set(key, queue);
      const remaining = Date.parse(attempt.deadlineAt) - this.now().getTime();
      entry.timer = setTimeout(() => void this.expireQueued(key, entry), Math.max(0, remaining));
      entry.timer.unref();
      void this.drain(key);
    });
    this.inFlight.set(submission.commandId, promise);
    void promise.finally(() => this.inFlight.delete(submission.commandId)).catch(() => undefined);
    return promise;
  }

  cancel(commandId: string): WorkTrackerMutationAttemptRecord {
    const attempt = this.options.store.requestWorkTrackerMutationCancellation(commandId);
    for (const [key, queue] of this.queues) {
      const entry = queue.find((candidate) => candidate.attempt.commandId === commandId);
      if (entry && !entry.active) void this.cancelQueued(key, entry);
    }
    return attempt;
  }

  status(
    limit = MAX_WORK_TRACKER_STATUS_ITEMS,
    scope: { taskId?: string; projectIds?: ReadonlySet<string> } = {}
  ): WorkTrackerMutationStatus[] {
    const attempts = this.options.store.listWorkTrackerMutationAttempts(
      Math.min(limit, MAX_WORK_TRACKER_STATUS_ITEMS),
      {
        taskId: scope.taskId,
        projectIds: scope.projectIds ? [...scope.projectIds] : undefined
      }
    );
    const pending = this.options.store.listPendingWorkTrackerMutationAttempts();
    const now = this.now().getTime();
    return attempts.map((attempt) => ({
      commandId: attempt.commandId,
      rootIntentId: attempt.rootIntentId,
      ...(attempt.predecessorCommandId ? { predecessorCommandId: attempt.predecessorCommandId } : {}),
      attemptOrdinal: attempt.attemptOrdinal,
      decision: attempt.decision,
      projectId: attempt.projectId,
      taskId: attempt.taskId,
      providerId: attempt.providerId,
      bindingId: attempt.bindingId,
      targetId: attempt.targetId,
      operation: attempt.operation,
      basisDigest: attempt.basisDigest,
      conflictScope: attempt.conflictScope,
      queueOrdinal: attempt.queueOrdinal,
      queuePosition: attempt.state === "terminal" ? 0 : Math.min(999, pending.filter((candidate) =>
        candidate.bindingId === attempt.bindingId && candidate.targetId === attempt.targetId &&
        candidate.conflictScope === attempt.conflictScope && candidate.queueOrdinal <= attempt.queueOrdinal).length),
      state: attempt.state,
      ...(attempt.outcome ? { outcome: attempt.outcome } : {}),
      requiredGuarantee: attempt.requiredGuarantee,
      availableGuarantee: attempt.availableGuarantee,
      ageMs: Math.max(0, now - Date.parse(attempt.createdAt)),
      ...(attempt.recoveryState ? { recoveryState: attempt.recoveryState.slice(0, 256) } : {})
    }));
  }

  private async drain(key: string): Promise<void> {
    const queue = this.queues.get(key);
    if (!queue?.length || queue.some((entry) => entry.active)) return;
    const entry = queue[0]!;
    entry.active = true;
    if (entry.timer) clearTimeout(entry.timer);
    try {
      const refreshed = this.options.store.getWorkTrackerMutationAttempt(entry.attempt.commandId);
      if (!refreshed || refreshed.state === "terminal") return entry.resolve(entry.submission.duplicateValue);
      if (refreshed.state === "dispatched" || refreshed.state === "reconciling") {
        if (refreshed.state === "dispatched") {
          this.options.store.transitionWorkTrackerMutation({
            commandId: refreshed.commandId, state: "reconciling", recoveryState: "owner_restart"
          });
        }
        const recovered = await this.reconcileWithinDeadline(
          entry,
          (signal) => entry.submission.recover(signal),
          "restart_reconciliation_timeout",
          "restart_reconciliation_failed"
        );
        this.options.store.finishWorkTrackerMutation({
          commandId: refreshed.commandId, outcome: recovered.outcome, recoveryState: recovered.recoveryState
        });
        return entry.resolve(recovered.value);
      }
      if (refreshed.cancellationRequested) return await this.finishWithoutDispatch(entry, "cancelled");
      if (Date.parse(refreshed.deadlineAt) <= this.now().getTime()) return await this.finishWithoutDispatch(entry, "timeout");
      if (entry.submission.capability.support !== "supported" ||
          entry.submission.capability.guarantee !== entry.submission.requiredGuarantee) {
        return await this.finishWithoutDispatch(entry, "unsupported_guarantee");
      }
      if (refreshed.state === "queued") {
        this.options.store.transitionWorkTrackerMutation({ commandId: refreshed.commandId, state: "admitted" });
      }
      try {
        await entry.submission.authorize();
      } catch {
        return await this.finishWithoutDispatch(entry, "denied_capability");
      }
      let prepared: WorkTrackerPreparation<unknown>;
      try {
        const preparation = await raceDeadline((signal) => entry.submission.prepare(signal), this.providerDeadlineMs);
        if (preparation.kind === "timeout") return await this.finishWithoutDispatch(entry, "timeout");
        prepared = preparation.value;
      } catch {
        const value = await entry.submission.finishRecoveryRequired("provider_preflight_failed");
        this.options.store.finishWorkTrackerMutation({
          commandId: refreshed.commandId, outcome: "recovery_required", recoveryState: "provider_preflight_failed"
        });
        return entry.resolve(value);
      }
      if (prepared.kind === "terminal") {
        this.options.store.finishWorkTrackerMutation({
          commandId: refreshed.commandId, outcome: prepared.outcome, recoveryState: prepared.recoveryState
        });
        return entry.resolve(prepared.value);
      }
      try {
        await entry.submission.authorize();
      } catch {
        return await this.finishWithoutDispatch(entry, "denied_capability");
      }
      // Authorization and preflight may yield while cancellation is persisted.
      // There must be no await between this final check and dispatch admission.
      if (this.options.store.getWorkTrackerMutationAttempt(refreshed.commandId)?.cancellationRequested) {
        return await this.finishWithoutDispatch(entry, "cancelled");
      }
      this.options.store.transitionWorkTrackerMutation({ commandId: refreshed.commandId, state: "dispatched" });
      let finished: WorkTrackerFinished<unknown>;
      try {
        const dispatched = await raceDeadline((signal) => prepared.dispatch(signal), this.providerDeadlineMs);
        if (dispatched.kind === "finished") finished = dispatched.value;
        else {
          this.options.store.transitionWorkTrackerMutation({ commandId: refreshed.commandId, state: "reconciling", recoveryState: "provider_timeout" });
          finished = await this.reconcileWithinDeadline(
            entry, (signal) => prepared.reconcile("timeout", signal), "provider_reconciliation_timeout", "provider_reconciliation_failed"
          );
        }
      } catch {
        this.options.store.transitionWorkTrackerMutation({ commandId: refreshed.commandId, state: "reconciling", recoveryState: "provider_error" });
        finished = await this.reconcileWithinDeadline(
          entry, (signal) => prepared.reconcile("error", signal), "provider_reconciliation_timeout", "provider_reconciliation_failed"
        );
      }
      this.options.store.finishWorkTrackerMutation({
        commandId: refreshed.commandId, outcome: finished.outcome, recoveryState: finished.recoveryState
      });
      entry.resolve(finished.value);
    } catch (error) {
      entry.reject(error);
    } finally {
      this.removeEntry(key, entry);
    }
  }

  private async expireQueued<T>(key: string, entry: RuntimeEntry<T>): Promise<void> {
    if (entry.active) return;
    await this.finishWithoutDispatch(entry, "timeout");
    this.removeEntry(key, entry);
  }

  private async cancelQueued<T>(key: string, entry: RuntimeEntry<T>): Promise<void> {
    if (entry.active) return;
    if (entry.timer) clearTimeout(entry.timer);
    await this.finishWithoutDispatch(entry, "cancelled");
    this.removeEntry(key, entry);
  }

  private async finishWithoutDispatch<T>(entry: RuntimeEntry<T>, outcome: "denied_capability" | "unsupported_guarantee" | "cancelled" | "timeout"): Promise<void> {
    try {
      const value = await entry.submission.finishWithoutDispatch(outcome);
      this.options.store.finishWorkTrackerMutation({ commandId: entry.attempt.commandId, outcome });
      entry.resolve(value);
    } catch (error) {
      entry.reject(error);
    }
  }

  private async reconcileWithinDeadline<T>(
    entry: RuntimeEntry<T>,
    reconciliation: (signal: AbortSignal) => Promise<WorkTrackerFinished<T>>,
    timeoutState: string,
    failureState: string
  ): Promise<WorkTrackerFinished<T>> {
    try {
      const result = await raceDeadline(reconciliation, this.providerDeadlineMs);
      if (result.kind === "finished") return result.value;
      const value = await entry.submission.finishRecoveryRequired(timeoutState);
      return { value, outcome: "recovery_required", recoveryState: timeoutState };
    } catch {
      const value = await entry.submission.finishRecoveryRequired(failureState);
      return { value, outcome: "recovery_required", recoveryState: failureState };
    }
  }

  private removeEntry(key: string, entry: RuntimeEntry<unknown>): void {
    const queue = this.queues.get(key);
    if (!queue) return;
    const index = queue.indexOf(entry);
    if (index >= 0) queue.splice(index, 1);
    if (queue.length === 0) this.queues.delete(key);
    else void this.drain(key);
  }

  private now(): Date { return (this.options.now ?? (() => new Date()))(); }
  private get maxQueueWaitMs(): number { return this.options.maxQueueWaitMs ?? DEFAULT_WORK_TRACKER_MAX_QUEUE_WAIT_MS; }
  private get providerDeadlineMs(): number { return this.options.providerDeadlineMs ?? DEFAULT_WORK_TRACKER_PROVIDER_DEADLINE_MS; }
}

function queueKey(attempt: Pick<WorkTrackerMutationAttemptRecord, "bindingId" | "targetId" | "conflictScope">): string {
  return JSON.stringify([attempt.bindingId, attempt.targetId, attempt.conflictScope]);
}

async function raceDeadline<T>(operation: (signal: AbortSignal) => Promise<T>, timeoutMs: number): Promise<{ kind: "finished"; value: T } | { kind: "timeout" }> {
  const controller = new AbortController();
  let timer: NodeJS.Timeout | undefined;
  try {
    const timeout = new Promise<{ kind: "timeout" }>((resolve) => {
      timer = setTimeout(() => {
        // Resolve the timeout first so abort-induced rejections cannot reclassify it.
        resolve({ kind: "timeout" });
        controller.abort();
      }, timeoutMs);
    });
    return await Promise.race([
      operation(controller.signal).then((value) => ({ kind: "finished" as const, value })),
      timeout
    ]);
  } finally {
    if (timer) clearTimeout(timer);
    // Fence late continuations before reconciliation or queue release.
    controller.abort();
  }
}

function assertPositiveBound(value: number, label: string): void {
  if (!Number.isSafeInteger(value) || value < 1 || value > 300_000) {
    throw new StorageError("invalid_state", `Work-tracker ${label} must be between 1 and 300000 milliseconds`);
  }
}

