import { test } from "vitest";
import assert from "node:assert/strict";
import { GiteaPullRequestAdapter } from "./gitea.js";
import { PullRequestError } from "./contract.js";

const head = "a".repeat(40);
const base = "b".repeat(40);
const repo = { id: 12, full_name: "team/project", default_branch: "main", allow_fast_forward_only_merge: true };
const pr = { id: 99, number: 7, state: "open", draft: false, merged: false,
  mergeable: true, updated_at: "2026-10-13T00:00:00Z", comments: 2,
  head: { ref: "work", sha: head, repo }, base: { ref: "main", sha: base, repo } };

function fixture(overrides: Record<string, unknown> = {}) {
  const calls: Array<{ method: string; path: string; body?: unknown }> = [];
  const routes = new Map<string, unknown>([
    ["GET /api/v1/repos/team/project", repo],
    ["GET /api/v1/repos/team/project/pulls/7", { ...pr, ...overrides }],
    ["GET /api/v1/repos/team/project/branches/main", { name: "main", commit: { id: base }, protected: true,
      enable_status_check: true, status_check_contexts: ["build"], required_approvals: 1 }],
    ["GET /api/v1/repos/team/project/pulls/7/reviews?limit=100&page=1", [
      { id: 5, user: { id: 44, login: "human", type: "User" }, state: "APPROVED", commit_id: head,
        dismissed: false, stale: false, submitted_at: "2026-10-13T00:00:00Z" },
      { id: 6, user: { id: 45, login: "robot", type: "Bot" }, state: "APPROVED", commit_id: head,
        dismissed: false, stale: false, submitted_at: "2026-10-13T00:00:00Z" },
      { id: 7, user: { id: 46, login: "observer", type: "User" }, state: "PENDING", commit_id: "",
        dismissed: false, stale: false, submitted_at: "2026-10-13T00:00:00Z" }
    ]],
    [`GET /api/v1/repos/team/project/commits/${head}/status?limit=100&page=1`,
      { sha: head, statuses: [{ context: "build", status: "success" }, { context: "advisory", status: "failure" }], total_count: 2 }],
    ["GET /api/v1/repos/team/project/pulls?state=all&limit=100&page=1", [{ ...pr, ...overrides }]],
    ["POST /api/v1/repos/team/project/pulls/7/merge", null]
  ]);
  const adapter = new GiteaPullRequestAdapter({ instanceId: "gitea", baseUrl: "https://forge.example/",
    owner: "team", name: "project", token: async () => "secret", fetcher: async (input, init) => {
      const url = new URL(String(input));
      const method = init?.method ?? "GET";
      calls.push({ method, path: url.pathname + url.search,
        ...(init?.body ? { body: JSON.parse(String(init.body)) as unknown } : {}) });
      const key = `${method} ${url.pathname}${url.search}`;
      return new Response(routes.has(key) ? JSON.stringify(routes.get(key)) : "", {
        status: routes.has(key) ? 200 : 404, headers: { "content-type": "application/json" } });
    } });
  return { adapter, calls, routes };
}

test("Gitea observation distinguishes required and advisory status, Human and bot reviews", async () => {
  const { adapter, calls } = fixture();
  const repository = await adapter.repository();
  const result = await adapter.read(repository, "7");
  assert.equal(result?.head.revision, head);
  assert.deepEqual(result?.requiredChecks, [{ context: "build", state: "success" }]);
  assert.deepEqual(result?.advisoryChecks, [{ context: "advisory", state: "failure" }]);
  assert.equal(result?.reviews[0]?.actor.kind, "human");
  assert.equal(result?.reviews[1]?.actor.kind, "bot");
  assert.equal(result?.reviews[2]?.decision, "pending");
  assert.equal(result?.reviews[2]?.stale, true);
  assert.equal(result?.discussionCount, 2);
  assert.equal(calls.some((call) => call.path.includes("/issues/") || call.path.includes("/actions/")), false);
});

test("Gitea rejects a PR whose native repository identity differs from its binding", async () => {
  const { adapter } = fixture({ head: { ref: "work", sha: head, repo: { ...repo, id: 13 } } });
  await assert.rejects(adapter.read(await adapter.repository(), "7"),
    (error: unknown) => error instanceof PullRequestError && error.code === "repository_mismatch");
});

test("Gitea merge dispatch sends exact head and never forces or queues merge", async () => {
  const { adapter, calls } = fixture();
  await adapter.mergeFastForward(await adapter.repository(), "7", head);
  assert.deepEqual(calls.at(-1)?.body, { do: "fast-forward-only", head_commit_id: head,
    force_merge: false, merge_when_checks_succeed: false, delete_branch_after_merge: false });
});

test("Gitea draft creation uses the configured WIP convention and reconciles by branch identity", async () => {
  let created = false;
  const calls: Array<{ method: string; path: string; body?: unknown }> = [];
  const adapter = new GiteaPullRequestAdapter({ instanceId: "gitea", baseUrl: "https://forge.example/",
    owner: "team", name: "project", token: async () => "secret", fetcher: async (input, init) => {
      const url = new URL(String(input));
      const method = init?.method ?? "GET";
      const path = url.pathname + url.search;
      calls.push({ method, path, ...(init?.body ? { body: JSON.parse(String(init.body)) as unknown } : {}) });
      if (path === "/api/v1/repos/team/project") return Response.json(repo);
      if (path === "/api/v1/repos/team/project/branches/work") return Response.json({ name: "work", commit: { id: head } });
      if (path === "/api/v1/repos/team/project/branches/main") return Response.json({ name: "main", commit: { id: base },
        protected: false, enable_status_check: false, status_check_contexts: [], required_approvals: 0 });
      if (path === "/api/v1/repos/team/project/pulls?state=all&limit=100&page=1") return Response.json(created ? [{ ...pr, draft: true }] : []);
      if (path === "/api/v1/repos/team/project/pulls/7") return Response.json({ ...pr, draft: true });
      if (path === "/api/v1/repos/team/project/pulls/7/reviews?limit=100&page=1") return Response.json([]);
      if (path === `/api/v1/repos/team/project/commits/${head}/status?limit=100&page=1`)
        return Response.json({ sha: head, statuses: [], total_count: 0 });
      if (method === "POST" && path === "/api/v1/repos/team/project/pulls") { created = true; return Response.json({ ...pr, draft: true }); }
      return new Response("", { status: 404 });
    } });
  const repository = await adapter.repository();
  const result = await adapter.createDraft(repository, "refs/heads/work", "refs/heads/main", head, "Feature");
  assert.equal(result.draft, true);
  assert.deepEqual(calls.find((call) => call.method === "POST")?.body,
    { head: "work", base: "main", title: "WIP: Feature" });
});

import { test } from "vitest";
import assert from "node:assert/strict";
import { requestExactMerge, type PullRequestAdapter, type PullRequestObservation, PullRequestError } from "./contract.js";

const sha = "a".repeat(40);
const base = "b".repeat(40);
const repository = { provider: "other", instanceId: "fixture", nativeId: "opaque/repo" };
const observation: PullRequestObservation = {
  repository, nativeId: "opaque-pr", head: { repository, ref: "refs/heads/work", revision: sha },
  base: { repository, ref: "refs/heads/main", revision: base }, state: "open", draft: false,
  mergeable: true, mergeStrategy: "fast-forward-only", requiredChecks: [], requiredApprovals: 1,
  reviews: [{ nativeId: "review-1", actor: { nativeId: "person-1", login: "person", kind: "human" },
    decision: "approved", headRevision: sha, dismissed: false, stale: false, submittedAt: "2026-10-13T00:00:00Z" }],
  discussionCount: 0, providerRevision: "rev-1"
};

test("exact merge admits a current human approval and verifies the resulting candidate", async () => {
  let calls = 0;
  let current = observation;
  const adapter: PullRequestAdapter = {
    read: async () => current,
    mergeFastForward: async () => { calls++; current = { ...observation, state: "merged", mergedRevision: sha }; }
  };
  const result = await requestExactMerge(adapter, { repository, nativeId: "opaque-pr", headRevision: sha,
    baseRef: "refs/heads/main", baseRevision: base, strategy: "fast-forward-only", requiredHumanActorId: "person-1" });
  assert.equal(result.mergedRevision, sha);
  assert.equal(calls, 1);
});

test.each([
  ["head_moved", { head: { ...observation.head, revision: "c".repeat(40) } }],
  ["approval_missing", { reviews: [{ ...observation.reviews[0]!, stale: true }] }],
  ["approval_missing", { reviews: [{ ...observation.reviews[0]!, actor: { nativeId: "bot", login: "bot", kind: "bot" as const } }] }],
  ["required_checks_incomplete", { requiredChecks: [{ context: "build", state: "pending" as const }] }],
  ["merge_conflict", { mergeable: false }],
  ["draft_pr", { draft: true }]
])("exact merge rejects %s before a provider write", async (code, change) => {
  let calls = 0;
  const adapter: PullRequestAdapter = { read: async () => ({ ...observation, ...change }),
    mergeFastForward: async () => { calls++; } };
  await assert.rejects(requestExactMerge(adapter, { repository, nativeId: "opaque-pr", headRevision: sha,
    baseRef: "refs/heads/main", baseRevision: base, strategy: "fast-forward-only", requiredHumanActorId: "person-1" }),
  (error: unknown) => error instanceof PullRequestError && error.code === code);
  assert.equal(calls, 0);
});

test("ambiguous merge never becomes success without an authenticated merged observation", async () => {
  const adapter: PullRequestAdapter = { read: async () => observation,
    mergeFastForward: async () => { throw new Error("timeout"); } };
  await assert.rejects(requestExactMerge(adapter, { repository, nativeId: "opaque-pr", headRevision: sha,
    baseRef: "refs/heads/main", baseRevision: base, strategy: "fast-forward-only", requiredHumanActorId: "person-1" }),
  (error: unknown) => error instanceof PullRequestError && error.code === "merge_outcome_unknown");
});

test("a later dismissed decision revokes an earlier approval from the same Human", async () => {
  let calls = 0;
  const adapter: PullRequestAdapter = { read: async () => ({ ...observation, reviews: [
    observation.reviews[0]!, { ...observation.reviews[0]!, nativeId: "review-2", dismissed: true,
      submittedAt: "2026-10-13T01:00:00Z" }
  ] }), mergeFastForward: async () => { calls++; } };
  await assert.rejects(requestExactMerge(adapter, { repository, nativeId: "opaque-pr", headRevision: sha,
    baseRef: "refs/heads/main", baseRevision: base, strategy: "fast-forward-only", requiredHumanActorId: "person-1" }),
  (error: unknown) => error instanceof PullRequestError && error.code === "approval_missing");
  assert.equal(calls, 0);
});

test("a moved base revision denies merge even when its ref is unchanged", async () => {
  let calls = 0;
  const adapter: PullRequestAdapter = { read: async () => ({ ...observation,
    base: { ...observation.base, revision: "c".repeat(40) } }), mergeFastForward: async () => { calls++; } };
  await assert.rejects(requestExactMerge(adapter, { repository, nativeId: "opaque-pr", headRevision: sha,
    baseRef: "refs/heads/main", baseRevision: base, strategy: "fast-forward-only",
    requiredHumanActorId: "person-1" }),
  (error: unknown) => error instanceof PullRequestError && error.code === "base_moved");
  assert.equal(calls, 0);
});

test("conflicting reviews with the same timestamp fail closed for opaque provider IDs", async () => {
  let calls = 0;
  const adapter: PullRequestAdapter = { read: async () => ({ ...observation, reviews: [
    { ...observation.reviews[0]!, nativeId: "alpha" },
    { ...observation.reviews[0]!, nativeId: "omega", decision: "changes_requested" }
  ] }), mergeFastForward: async () => { calls++; } };
  await assert.rejects(requestExactMerge(adapter, { repository, nativeId: "opaque-pr", headRevision: sha,
    baseRef: "refs/heads/main", baseRevision: base, strategy: "fast-forward-only",
    requiredHumanActorId: "person-1" }), (error: unknown) =>
    error instanceof PullRequestError && error.code === "approval_ambiguous");
  assert.equal(calls, 0);
});

import assert from "node:assert/strict";
import { execFile } from "node:child_process";
import { randomUUID } from "node:crypto";
import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { promisify } from "node:util";
import { test } from "vitest";
import { readCiCredential } from "../ci/credential.js";
import { GiteaGitPushPort } from "../hosting/gitPush.js";
import { GiteaHostingAdapter } from "../hosting/gitea.js";
import { trustedOwnerGitEnvironment } from "../gitExecution.js";
import { GiteaPullRequestAdapter } from "./gitea.js";

const git = promisify(execFile);
const config = {
  baseUrl: process.env.PI_GITEA_PR_TEST_BASE_URL,
  owner: process.env.PI_GITEA_PR_TEST_OWNER,
  repository: process.env.PI_GITEA_PR_TEST_REPOSITORY,
  repositoryId: process.env.PI_GITEA_PR_TEST_REPOSITORY_ID,
  gitUsername: process.env.PI_GITEA_PR_TEST_GIT_USERNAME,
  hostingCredentialRef: process.env.PI_GITEA_PR_TEST_HOSTING_CREDENTIAL_REF,
  prCredentialRef: process.env.PI_GITEA_PR_TEST_PR_CREDENTIAL_REF
};
const ready = Object.values(config).every((value) => typeof value === "string" && value.length > 0) &&
  process.env.PI_GITEA_PR_TEST_DISPOSABLE_REPOSITORY === "1" && !!process.env.CREDENTIALS_DIRECTORY;

/** Opt-in provider check; mutates only uniquely named branches in a disposable repository. */
test.skipIf(!ready)("real Gitea draft, readiness and exact fast-forward merge", async () => {
  assert.equal(new URL(config.baseUrl!).protocol, "https:");
  const root = await mkdtemp(join(tmpdir(), "relayview-pr-real-"));
  const suffix = randomUUID();
  const baseRef = `refs/heads/relayview/pr-smoke/base/${suffix}`;
  const headRef = `refs/heads/relayview/pr-smoke/head/${suffix}`;
  const hostToken = () => readCiCredential(config.hostingCredentialRef!);
  const prToken = () => readCiCredential(config.prCredentialRef!);
  const port = new GiteaGitPushPort({ sourceWorktree: root, baseUrl: config.baseUrl!,
    owner: config.owner!, repository: config.repository!, gitUsername: config.gitUsername!, token: hostToken });
  const adapter = new GiteaPullRequestAdapter({ instanceId: "pr-real-smoke", baseUrl: config.baseUrl!,
    owner: config.owner!, name: config.repository!, token: prToken });
  let base: string | undefined;
  let head: string | undefined;
  let prId: string | undefined;
  let mergedConfirmed = false;
  try {
    const env = trustedOwnerGitEnvironment();
    await git("git", ["init", "--quiet", root], { env });
    const commit = async (message: string) => git("git", ["-C", root, "-c", "core.hooksPath=/dev/null",
      "-c", "user.name=RelayView smoke", "-c", "user.email=pr-smoke@example.invalid",
      "commit", "--allow-empty", "--quiet", "-m", message], { env });
    await commit("PR smoke base");
    base = (await git("git", ["-C", root, "rev-parse", "HEAD"], { env })).stdout.trim();
    await commit("PR smoke head");
    head = (await git("git", ["-C", root, "rev-parse", "HEAD"], { env })).stdout.trim();
    const repository = await adapter.repository();
    assert.equal(repository.nativeId, config.repositoryId);
    await port.push(baseRef, base, null);
    await port.push(headRef, head, null);
    const draft = await adapter.createDraft(repository, headRef, baseRef, head, `PR smoke ${suffix}`);
    prId = draft.nativeId;
    assert.equal(draft.draft, true);
    await assert.rejects(adapter.mergeFastForward(repository, prId, head),
      "a draft must be denied by the provider before readiness");
    const readyPr = await adapter.markReady(repository, prId, head);
    assert.equal(readyPr.draft, false);
    await adapter.mergeFastForward(repository, prId, head);
    const merged = await adapter.read(repository, prId);
    assert.equal(merged?.state, "merged");
    assert.equal(merged?.mergedRevision, head);
    mergedConfirmed = true;
  } finally {
    try {
      const repository = await adapter.repository();
      if (prId) {
        const observed = await adapter.read(repository, prId);
        if (observed?.state === "open") {
          const token = await prToken();
          const url = new URL(`api/v1/repos/${encodeURIComponent(config.owner!)}/${encodeURIComponent(config.repository!)}/pulls/${prId}`,
            config.baseUrl!);
          const closed = await fetch(url, { method: "PATCH", headers: { Authorization: `token ${token}`,
            "Content-Type": "application/json" }, body: JSON.stringify({ state: "closed" }), redirect: "error" });
          assert.equal(closed.ok, true, "disposable smoke PR needs manual cleanup");
        }
      }
      for (const [ref, expected] of [[headRef, head], [baseRef, mergedConfirmed ? head : base]] as const) {
        if (!expected) continue;
        const observed = await portBranch(ref);
        if (!observed) continue;
        assert.equal(observed, expected, `disposable smoke branch ${ref} moved; inspect before cleanup`);
        await port.deleteExact(ref, expected);
      }
    } finally { await rm(root, { recursive: true, force: true }); }
  }

  async function portBranch(ref: string): Promise<string | undefined> {
    const repository = await adapter.repository();
    return (await new GiteaHostingAdapter({ instanceId: "pr-real-smoke",
      baseUrl: config.baseUrl!, owner: config.owner!, name: config.repository!, token: hostToken })
      .branch(repository, ref))?.revision;
  }
}, 180_000);
